import { join as join9 } from "node:path";
var WAKE_PLANE_CAPABILITY = "wake.create";
var WAKE_PLANE_STATUS_TTL_MS = 5 * 60 * 1000;
var WAKE_PLANE_HANDSHAKE_TIMEOUT_MS = 2000;
