  if (cached && now() < cached.expiresAt)
    return cached.status;
  if (inFlightProbe)
    return await inFlightProbe;
  const startedAt = now();
  const probe = probeStatus().then((status) => {
    cachedStatus = { status, expiresAt: startedAt + WAKE_PLANE_STATUS_TTL_MS };
    return status;
  });
