// src/features/magic-context/dreamer/open-opencode-db.ts
function openOpenCodeDb() {
  if (!harnessOwnsOpenCodeStore2())
    return null;
  const resolution = resolveOpenCodeDbPath();
  const dbPath = resolution.path;
  if (!openCodeDbPathExists(resolution)) {
    if (claimOpenCodeDbDiagnosticOnce("dreamer-missing", resolution)) {
      log2(`[dreamer] OpenCode DB not found at ${dbPath} (source=${resolution.source}) — skipping OpenCode history scan`);
    }
    return null;
  }
  try {
    const db = new Database2(dbPath, { readonly: true });
    try {
      assertOpenCodeStoreGeneration(db, "v1", dbPath);
    } catch (error) {
      db.close();
      throw error;
    }
    db.exec("PRAGMA busy_timeout = 5000");
    clearOpenCodeDbReadFailure();
    return db;
  } catch (error) {
    recordOpenCodeDbReadFailure(resolution, error);
    if (claimOpenCodeDbDiagnosticOnce("dreamer-open-failure", resolution)) {
      log2(`[dreamer] failed to open OpenCode DB at ${dbPath} (source=${resolution.source}): ${getErrorMessage(error)}`);
    }
    return null;
  }
}

