// src/hooks/magic-context/channel2-delivery.ts
async function deliverSyntheticUserMessage(sessionId, deps) {
  const promptContext = await resolvePromptContext2(deps.client, sessionId);
  const body = {
    noReply: false,
    parts: [{ type: "text", text: deps.text, synthetic: true }]
  };
  if (promptContext?.agent)
    body.agent = promptContext.agent;
  if (promptContext?.model) {
    body.model = {
      providerID: promptContext.model.providerID,
      modelID: promptContext.model.modelID
    };
  }
  if (promptContext?.variant)
    body.variant = promptContext.variant;
  if (deps.beforeSend && !deps.beforeSend())
    return false;
  const session = deps.client.session;
  if (typeof session?.promptAsync !== "function") {
    throw new Error("client has no session.promptAsync");
  }
  await session.promptAsync({ path: { id: sessionId }, body });
  return true;
}

// src/hooks/magic-context/rust-refusal-recovery.ts
var RUST_REFUSAL_RECOVERY_PROMPT = "Magic Context's engine reconnected. Continue from where you stopped.";
